import React, { useState, useEffect } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";

function Register() {
  const location = useLocation();

  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
  });

  const [showQR, setShowQR] = useState(false);
  const [screenshot, setScreenshot] = useState(null);
  const [statusMsg, setStatusMsg] = useState("");

  // 🔥 NEW STATES
  const [userId, setUserId] = useState("");
  const [approved, setApproved] = useState(false);

  /* INPUT HANDLE */
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  /* SHOW PAYMENT */
  const handlePayment = (e) => {
    e.preventDefault();
    setShowQR(true);
  };

  /* SUBMIT WITH SCREENSHOT */
  const confirmPayment = async () => {
    if (!screenshot) {
      return alert("⚠️ Screenshot upload pannunga!");
    }

    const form = new FormData();
    Object.keys(formData).forEach((key) => {
      form.append(key, formData[key]);
    });
    form.append("screenshot", screenshot);

    try {
      const res = await axios.post(
        "http://localhost:5000/register",
        form,
        { headers: { "Content-Type": "multipart/form-data" } }
      );

      if (res.data.success) {
        setUserId(res.data.userId); // 🔥 IMPORTANT
        setStatusMsg("⏳ Waiting for admin approval");
        alert("✅ Submitted successfully");
      }
    } catch (err) {
      console.log(err);
      alert("❌ Upload failed");
    }
  };

  /* 🔥 CHECK APPROVAL STATUS */
  const checkStatus = async () => {
    if (!userId) return;

    try {
      const res = await axios.get(
        `http://localhost:5000/verify-user/${userId}`
      );

      if (res.data.success) {
        if (res.data.user.payment_status === "approved") {
          setApproved(true);
          setStatusMsg("✅ Payment Approved!");
        }
      }
    } catch (err) {
      console.log(err);
    }
  };

  /* 🔥 AUTO CHECK EVERY 5 SEC */
  useEffect(() => {
  const interval = setInterval(async () => {
    if (!userId) return;

    try {
      const res = await axios.get(
        `http://localhost:5000/verify-user/${userId}`
      );

      if (res.data.success) {
        if (res.data.user.payment_status === "approved") {
          setApproved(true);
          setStatusMsg("✅ Payment Approved!");
        }
      }
    } catch (err) {
      console.log(err);
    }
  }, 5000);

  return () => clearInterval(interval);
}, [userId]);

  /* UPI STRING */
  const upiString = `upi://pay?pa=arunsekar664@okaxis&pn=Event&am=100&cu=INR`;

  /* STYLES */
  const box = {
    padding: "20px",
    borderRadius: "10px",
    background: "#222",
    width: "300px",
    margin: "auto",
  };

  const input = {
    padding: "10px",
    margin: "5px",
    width: "100%",
  };

  const btn = {
    padding: "10px",
    background: "orange",
    border: "none",
    cursor: "pointer",
  };

  return (
    <div style={{ textAlign: "center", color: "white" }}>
      <Navbar />
      <h2>🚀 Event Registration</h2>

      {/* FORM */}
      {!showQR && (
        <form onSubmit={handlePayment} style={box}>
          <input name="name" placeholder="Name" style={input} onChange={handleChange} required />
          <input name="college_name" placeholder="College" style={input} onChange={handleChange} required />
          <input name="phone" placeholder="Phone" style={input} onChange={handleChange} required />
          <input name="email" placeholder="Email" style={input} onChange={handleChange} required />

          <h3>{eventName}</h3>
          <button style={btn}>Proceed to Pay</button>
        </form>
      )}

      {/* PAYMENT SCREEN */}
      {showQR && !approved && (
        <div style={box}>
          <h3>📲 Scan & Pay</h3>
          <QRCode value={upiString} size={200} />

          <p>Pay ₹100 and upload screenshot</p>

          <input
            type="file"
            accept="image/*"
            onChange={(e) => setScreenshot(e.target.files[0])}
          />

          <button style={btn} onClick={confirmPayment}>
            Submit Payment
          </button>

          {statusMsg && <p>{statusMsg}</p>}
        </div>
      )}

      {/* ✅ AFTER APPROVAL */}
      {approved && (
        <div style={box}>
          <h3>🎉 Payment Approved</h3>

          <QRCode value={userId} size={180} />

          <p>Your Entry QR</p>
        </div>
      )}
    </div>
  );
}

export default Register;
